/** Checkpoint 1 band/verdict reader tests — node --test, fixtures only (no Python). */

// tests/fixtures/real-verdict.jsonl is hand-derived from harness/measure.py
// (class Band's formulas, screen_verdict, promote_bar — see the comments in
// app/static/band.js for the exact lines) to produce the *real* emitted band
// shape (an asdict(Band) object), unlike tests/fixtures/fake-events.jsonl's
// verdicts, which carry fake_run.py's legacy [lo, hi] shape. It is NOT
// generated by running the harness and must never be regenerated.

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { readBand, verdictReading, SCREEN_ADVANCE_SD, BAND_FIELDS } from "./band.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REAL_VERDICT_FIXTURE = join(
  __dirname,
  "..",
  "..",
  "tests",
  "fixtures",
  "real-verdict.jsonl",
);
const FAKE_EVENTS_FIXTURE = join(
  __dirname,
  "..",
  "..",
  "tests",
  "fixtures",
  "fake-events.jsonl",
);
const MEASURE_PY = join(__dirname, "..", "..", "harness", "measure.py");

function loadJsonl(path) {
  const text = readFileSync(path, "utf8");
  return text
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line));
}

function loadRealVerdicts() {
  return loadJsonl(REAL_VERDICT_FIXTURE);
}

describe("band — readBand shapes", () => {
  it("test_readBand_measure_shape", () => {
    const raw = { sigma_screen: 0.02, bar: 0.01, source: "fixed_pair" };
    const result = readBand(raw);
    assert.equal(result.shape, "measure");
    assert.equal(result.fields, raw);
  });

  it("test_readBand_legacy_shape", () => {
    const result = readBand([0.5, 0.52]);
    assert.equal(result.shape, "legacy");
    assert.deepEqual(result.fields, { lo: 0.5, hi: 0.52 });
  });

  it("test_readBand_none_shape", () => {
    for (const raw of [null, undefined, [], [0.5], [0.5, 0.52, 0.6], ["a", "b"], "band", 5]) {
      const result = readBand(raw);
      assert.equal(result.shape, "none", `expected none for ${JSON.stringify(raw)}`);
      assert.equal(result.fields, null);
    }
  });

  it("test_readBand_never_throws", () => {
    for (const raw of [null, undefined, {}, [], NaN, Symbol("x")]) {
      assert.doesNotThrow(() => readBand(raw));
    }
  });
});

describe("band — verdictReading against the real fixture", () => {
  it("test_screening_verdict_threshold_is_sd_delta_screen_derived", () => {
    const verdicts = loadRealVerdicts();
    const screening = verdicts.find((e) => e.type === "verdict" && e.state === "inconclusive");
    const reading = verdictReading(screening);
    assert.equal(reading.shape, "measure");
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, screening.delta_mean);
    // harness/measure.py:194: delta >= SCREEN_ADVANCE_SD * band.sd_delta_screen
    assert.equal(reading.threshold, SCREEN_ADVANCE_SD * screening.band.sd_delta_screen);
    assert.equal(reading.thresholdLabel, "sd_delta_screen");
    assert.ok(reading.value < reading.threshold);
    assert.equal(reading.side, "below");
  });

  it("test_promoted_verdict_threshold_is_bar", () => {
    const verdicts = loadRealVerdicts();
    const promoted = verdicts.find((e) => e.type === "verdict" && e.state === "promoted");
    const reading = verdictReading(promoted);
    assert.equal(reading.shape, "measure");
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, promoted.delta_mean);
    // harness/measure.py:199-200: promote_bar(band) returns band.bar's value
    assert.equal(reading.threshold, promoted.band.bar);
    assert.equal(reading.thresholdLabel, "bar");
    assert.ok(reading.value > reading.threshold);
    assert.equal(reading.side, "above");
  });
});

describe("band — verdictReading edge shapes", () => {
  it("test_legacy_band_verdict_has_null_threshold", () => {
    // fake-events.jsonl (committed, not regenerated) still carries
    // fake_run.py's legacy [lo, hi] band shape on every verdict.
    const events = loadJsonl(FAKE_EVENTS_FIXTURE);
    const legacyVerdict = events.find((e) => e.type === "verdict" && Array.isArray(e.band));
    assert.ok(legacyVerdict, "expected at least one verdict with an array band in fake-events.jsonl");
    const reading = verdictReading(legacyVerdict);
    assert.equal(reading.shape, "legacy");
    assert.equal(reading.threshold, null);
    assert.equal(reading.thresholdLabel, null);
    assert.equal(reading.side, null);
  });

  it("test_band_absent_verdict_still_reports_value", () => {
    const verdict = {
      type: "verdict",
      state: "promoted",
      metric: "cvr_auc",
      delta_mean: 0.02,
      scores: [0.53],
      // no "band" key at all
    };
    const reading = verdictReading(verdict);
    assert.equal(reading.shape, "none");
    assert.equal(reading.threshold, null);
    assert.equal(reading.side, null);
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, 0.02); // the number is never suppressed
  });
});

describe("band — sync with harness/measure.py", () => {
  it("test_band_fields_match_python", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    // Same comment-stripping approach as reducer.test.js's extractTuple:
    // a trailing "#..." comment could otherwise smuggle stray tokens in.
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    const m = srcNoComments.match(/class Band:\n([\s\S]*?)\n\s*\n/);
    assert.ok(m, "could not find class Band in harness/measure.py");
    const body = m[1];
    const fieldRe = /^\s+(\w+)\s*:/gm;
    const fields = [];
    let fm;
    while ((fm = fieldRe.exec(body)) !== null) {
      fields.push(fm[1]);
    }
    assert.deepEqual(fields, BAND_FIELDS);
  });

  it("test_screen_advance_sd_matches_python", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    const m = srcNoComments.match(/SCREEN_ADVANCE_SD\s*=\s*([0-9.]+)/);
    assert.ok(m, "could not find SCREEN_ADVANCE_SD in harness/measure.py");
    assert.equal(Number(m[1]), SCREEN_ADVANCE_SD);
  });
});

describe("band — real fixture is internally consistent with harness/measure.py", () => {
  it("test_real_fixture_band_keys_match_python", () => {
    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      assert.ok(ev.band && typeof ev.band === "object", `expected an object band on seq ${ev.seq}`);
      assert.deepEqual(
        Object.keys(ev.band).sort(),
        [...BAND_FIELDS].sort(),
        `band keys on seq ${ev.seq} must match BAND_FIELDS`,
      );
    }
  });

  it("test_real_fixture_bar_is_internally_consistent", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    // harness/measure.py:21: PROMOTE_FLOOR = 0.010
    const floorM = srcNoComments.match(/PROMOTE_FLOOR\s*=\s*([0-9.]+)/);
    assert.ok(floorM, "could not find PROMOTE_FLOOR in harness/measure.py");
    // harness/measure.py:23: PROMOTE_Z_OVER_SQRT_K = 0.95
    const zM = srcNoComments.match(/PROMOTE_Z_OVER_SQRT_K\s*=\s*([0-9.]+)/);
    assert.ok(zM, "could not find PROMOTE_Z_OVER_SQRT_K in harness/measure.py");
    const PROMOTE_FLOOR = Number(floorM[1]);
    const PROMOTE_Z_OVER_SQRT_K = Number(zM[1]);

    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      const band = ev.band;
      // harness/measure.py:116-117 (_bar_from):
      //   def _bar_from(sd_delta_full: float) -> float:
      //       return max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * float(sd_delta_full))
      const expectedBar = Math.max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * band.sd_delta_full);
      assert.ok(
        Math.abs(band.bar - expectedBar) < 1e-9,
        `seq ${ev.seq}: bar=${band.bar} does not match max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * sd_delta_full)=${expectedBar} — fix the fixture, not this test`,
      );
    }
  });

  it("test_sd_delta_screen_is_internally_consistent", () => {
    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      const band = ev.band;
      // harness/measure.py:112-113 (_sd_delta):
      //   def _sd_delta(sigma: float, rho: float) -> float:
      //       return float(sigma) * math.sqrt(2.0 * (1.0 - float(rho)))
      const expected = band.sigma_screen * Math.sqrt(2.0 * (1.0 - band.rho));
      assert.ok(
        Math.abs(band.sd_delta_screen - expected) < 1e-5,
        `seq ${ev.seq}: sd_delta_screen=${band.sd_delta_screen} does not match sigma_screen * sqrt(2 * (1 - rho))=${expected} — fix the fixture, not this test`,
      );
    }
  });
});
